class ChunkExecutor:
    """每 refresh 步要一段新动作，重叠区做时间集成。"""

    def __init__(self, policy, H=50, refresh=10, w_new=0.6):
        self.policy, self.H = policy, H
        self.refresh, self.w = refresh, w_new
        self.buf, self.t = [], 0

    def step(self, obs):
        if self.t % self.refresh == 0 or not self.buf:
            new = self.policy.predict(obs, horizon=self.H)
            k = min(len(self.buf), len(new))
            for i in range(k):                      # 重叠区：新块为主加权
                self.buf[i] = self.w * new[i] + (1 - self.w) * self.buf[i]
            self.buf.extend(new[k:])                # 拼接非重叠部分
        self.t += 1
        return self.buf.pop(0)
